## 旧代码让判题失败的原因（按可能性排序）

| 报错类型 | 原因 | 旧代码写法 |
|---|---|---|
| **编译错误 CE** | `for (auto [x, y] : comps)` 是 **C++17** 的结构化绑定，判题机若用 C++11/14 直接编译失败 | 改成 `comps[i].first / .second` |
| **MLE / RE** | `vector<vector<char>> adj(n, vector<char>(n))` 是 $O(N^2)$ 内存。$N=10^5$ 就要 $10^{10}$ 字节，直接爆 | 改成**不显式建补图**，用“未访问链表 + 原图邻接表标记”跑补图 BFS，$O(N+M)$ |
| **RE / 玄学 WA** | `bitset<200005>` 是编译期定长，$N$ 超过 200005 就数组越界 | 改成**动态** `vector<unsigned long long>` 位集 |

逻辑本身（补图二分 + 每块背包）在样例 $N=5$ 上是对的，我手算验证答案 4。

## 加固版代码（C++11 起可编译）

改动：补图不再显式建边（省内存）、不再用结构化绑定、动态位集、并额外加了一道 $O(N+M)$ 的“同色类必须是团”校验（用来更稳地判 `-1`）。

```cpp
#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

// dst |= src << s，按 64 位字做移位
static void orShift(vector<unsigned long long> &dst,
                    const vector<unsigned long long> &src,
                    int s, int W) {
    int ws = s >> 6, bs = s & 63;
    if (ws >= W) return;
    if (bs == 0) {
        for (int i = W - 1; i >= ws; --i) dst[i] |= src[i - ws];
    } else {
        for (int i = W - 1; i >= ws; --i) {
            unsigned long long v = src[i - ws] << bs;
            if (i - ws - 1 >= 0) v |= src[i - ws - 1] >> (64 - bs);
            dst[i] |= v;
        }
    }
}

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    vector<vector<int> > adj(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u; --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    // ---------- 在补图上 BFS，但不真的把补图建出来 ----------
    vector<int> color(n, -1), mark(n, -1);
    vector<int> nx(n + 1), pv(n + 1);      // 未访问顶点链表，n 号是哨兵
    for (int i = 0; i < n; ++i) {
        nx[i] = (i + 1 < n) ? i + 1 : n;
        pv[i] = (i > 0) ? i - 1 : n;
    }
    nx[n] = (n > 0) ? 0 : n;
    pv[n] = (n > 0) ? n - 1 : n;

    vector<pair<int,int> > comps;           // 每块的 (颜色0点数, 颜色1点数)
    vector<int> q; q.reserve(n);

    while (nx[n] != n) {                    // 链表里还有未访问点
        int s = nx[n];
        nx[pv[s]] = nx[s]; pv[nx[s]] = pv[s];   // 取出并删除 s

        color[s] = 0;
        int cnt[2] = {1, 0};
        q.clear(); q.push_back(s);

        for (size_t qi = 0; qi < q.size(); ++qi) {
            int u = q[qi];
            for (size_t j = 0; j < adj[u].size(); ++j) mark[adj[u][j]] = u; // 标记原图邻居
            int v = nx[n];
            while (v != n) {
                int nv = nx[v];
                if (mark[v] != u) {         // 原图无边 => 补图有边
                    color[v] = color[u] ^ 1;
                    ++cnt[color[v]];
                    nx[pv[v]] = nv; pv[nv] = pv[v];
                    q.push_back(v);
                }
                v = nv;
            }
        }
        comps.push_back(make_pair(cnt[0], cnt[1]));
    }

    // ---------- 合法性校验：同色两类在原图里必须各自是团 ----------
    long long tot[2] = {0, 0}, ein[2] = {0, 0};
    for (int i = 0; i < n; ++i) ++tot[color[i]];
    for (int u = 0; u < n; ++u)
        for (size_t j = 0; j < adj[u].size(); ++j) {
            int v = adj[u][j];
            if (u < v && color[u] == color[v]) ++ein[color[u]];
        }
    for (int c = 0; c < 2; ++c)
        if (ein[c] != tot[c] * (tot[c] - 1) / 2) { printf("-1\n"); return 0; }

    // ---------- 背包：dp[a] = 第一组能否恰好 a 个点 ----------
    int W = (n + 64) / 64;                  // 需要 0..n 共 n+1 位
    vector<unsigned long long> dp(W, 0), ndp(W, 0);
    dp[0] = 1ULL;
    for (size_t i = 0; i < comps.size(); ++i) {
        fill(ndp.begin(), ndp.end(), 0ULL);
        orShift(ndp, dp, comps[i].first,  W);   // 每块二选一，必须从旧 dp 出发
        orShift(ndp, dp, comps[i].second, W);
        dp.swap(ndp);
    }

    long long ans = -1;
    for (int a = 0; a <= n; ++a) {
        if (((dp[a >> 6] >> (a & 63)) & 1ULL) == 0) continue;
        long long b = n - a;
        long long val = (long long)a * (a - 1) / 2 + b * (b - 1) / 2;
        if (ans < 0 || val < ans) ans = val;
    }
    printf("%lld\n", ans);
    return 0;
}
```

复杂度：$O(N+M)$ 染色 + $O(N+M)$ 校验 + $O(\frac{N^2}{64})$ 背包，内存 $O(N+M)$。

## 如果这版仍然失败，我需要你提供三项信息

1. **判题提示是哪种错误**：`Compile Error` / `Wrong Answer` / `Time Limit` / `Memory Limit` / `Runtime Error`？（最好贴报错原文，CE 一般会指出哪一行）
2. **$N, M$ 的范围**（题目描述里那段被截掉了，我拿不到）：$N\le 5000$？$10^5$？$10^6$？
3. 如果是 **WA**，给我一组能让它出错的输入和你的期望输出；如果是 TLE，告诉我 $N$ 大约多大。

> 特别地：若报的是 **WA**，那说明这版代码共用的核心逻辑还缺东西，并非只是写法问题；这时第 3 项就是关键，我会直接按那组数据查。

另外，如果 $N$ 真的到了 $10^6$ 级别，现在的背包 $O(N^2/64)$ 也顶不住，需要换成“把相同大小的块合并 + 多重背包前缀和”的做法。告诉我范围，我再给出那一版。

#ifndef BZ
#pragma GCC optimize "-O3"
#endif
#include <bits/stdc++.h>

#define FASTIO

#ifdef FASTIO
#define scanf abacaba
#define printf abacaba
#endif

typedef long long ll;
typedef long double ld;
typedef unsigned long long ull;

using namespace std;


/*
ll pw(ll a, ll b) {
	ll ans = 1; while (b) {
		while (!(b & 1)) b >>= 1, a = (a * a) % MOD;
		ans = (ans * a) % MOD, --b;
	} return ans;
}
*/

int n, m;

int ed[1000][1000];

int cl[2];
int cc[1200];
int was[1000];
int dp[1000];

void dfs1(int v, int c) {
	++cl[c];
	cc[v] = c;
	was[v] = 1;
	for (int i = 0; i < n; ++i) {
		if (i == v || ed[i][v])
			continue;
		if (was[i] && cc[i] == cc[v]) {
			cout << -1 << "\n";
			exit(0);
		}
		if (!was[i])
			dfs1(i, c ^ 1);
	}
}


int main() {
#ifdef FASTIO
	ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
#endif
	cin >> n >> m;
	for (int i = 0; i < m; ++i) {
		int a, b;
		cin >> a >> b;
		--a, --b;
		ed[a][b] = ed[b][a] = 1;
	}
	dp[0] = 1;
	for (int i = 0; i < n; ++i)
		if (!was[i]) {
			cl[0] = cl[1] = 0;
			dfs1(i, 0);
			for (int j = n; j >= 0; --j) {
				int x = 0;
				if (j >= cl[0])
					x |= dp[j - cl[0]];
				if (j >= cl[1])
					x |= dp[j - cl[1]];
				dp[j] = x;
			}
		}
	int ans = n * n;
	for (int i = 0; i <= n; ++i)
		if (dp[i])
			ans = min(ans, i * (i - 1) / 2 + (n - i) * (n - i - 1) / 2);
	cout << ans << "\n";
	return 0;
}

